// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    PRIVATE_ETH_CELL c;
    function setUp() public { c = new PRIVATE_ETH_CELL(); }
    function testFuzz_property(uint256 v1, uint256 v2) public {
        vm.assume(v1 != v2);
        // pre-initialization: MinSum is set to the fuzzed v1
        c.SetMinSum(v1);
        assertTrue(c.MinSum() == v1, "MinSum should equal first SetMinSum value");
        c.Initialized();
        // post-initialization: SetMinSum is guarded and must revert
        bool ok;
        try c.SetMinSum(v2) { ok = true; } catch { ok = false; }
        assertTrue(!ok, "SetMinSum must revert after initialization");
    }
}
